#include <stddef.h>

enum Status {
    OK = 200,
    NOT_FOUND = 404,
    SERVER_ERROR = 500
};

const char *get_status_string(enum Status status) {
    switch (status) {
        case OK:
            return "Success";
        case NOT_FOUND:
            return "Not found";
        case SERVER_ERROR:
            return "Server error";
        default:
            unreachable();
    }
}

enum Color : char {
    RED = 1,
    ORANGE,
    YELLOW,
    GREEN,
    BLUE,
    INDIGO,
    VIOLET
};

struct Student {
    char name[50];
    unsigned int id;
    unsigned int semester;
    float gpa;
};

// Positional initialization - values matches field order
struct Student alice = { "Alice", 123, 2, 3.8 };
// Designated initializer (since C99)
struct Student bob = {
    .name = "Bob",
    .id = 246,
    .semester = 1,
    .gpa = 3.9
};

struct Properties {
    // three fields can be compactly packed in one byte
    unsigned char visible : 1; // a occupies 1 bit
    unsigned char color : 3; // b occupies 3 bits
    unsigned char size : 4; // c occupies 4 bits
};
